	["TANK"] = "UI-LFG-RoleIcon-Tank-Background",
	["HEALER"] = "UI-LFG-RoleIcon-Healer-Background",
	["DAMAGER"] = "UI-LFG-RoleIcon-DPS-Background",
	["NONE"] = "UI-LFG-RoleIcon-DPS-Background",
};

