{ 'Blizzard_SharedXMLBase\\AddOnUtil.lua', [[
AddOnUtil = {};

local function GetAddOnDependenciesRecursive(addonName, dependencyArray, dependencyTable)
	-- dependencyArray keeps dependencies in a correct sorted order, dependencyTable keeps track of which were already added
	dependencyArray = dependencyArray or {};
	dependencyTable = dependencyTable or {};

	local dependencies = { C_AddOns.GetAddOnDependencies(addonName) };
	for _, depAddonName in ipairs(dependencies) do
		if not dependencyTable[depAddonName] then
			dependencyTable[depAddonName] = true;
			GetAddOnDependenciesRecursive(depAddonName, dependencyArray, dependencyTable);
			table.insert(dependencyArray, depAddonName);
		end
	end

	return dependencyArray, dependencyTable;
end

local function SetAddOnEnabled(addonName, enabled)
	if enabled then
		C_AddOns.EnableAddOn(addonName);
	else
		C_AddOns.DisableAddOn(addonName);
	end
end

local function EnableAndLoadAddOnHelper(addonName, restoreEnabledState)
	local previousState = (C_AddOns.GetAddOnEnableState(addonName) > 0);
	C_AddOns.EnableAddOn(addonName);
	local loaded, message = C_AddOns.LoadAddOn(addonName);

	if restoreEnabledState then
		SetAddOnEnabled(addonName, previousState);
	end

	return loaded, message;
end

function AddOnUtil.LoadAddOn(addonName, restoreEnabledState)
	if not C_AddOns.IsAddOnLoaded(addonName) then
		local dependencyArray = GetAddOnDependenciesRecursive(addonName);
		for _, depAddonName in ipairs(dependencyArray) do
			if not C_AddOns.IsAddOnLoaded(depAddonName) then
				EnableAndLoadAddOnHelper(depAddonName, restoreEnabledState);
			end
		end
		return EnableAndLoadAddOnHelper(addonName, restoreEnabledState);
	end

	return true; -- It was already loaded, no status message for addons that are already loaded.
end

function AddOnUtil.SetEnableStateForAddOnAndDependencies(addonName, character, enabled)
	local setter = enabled and C_AddOns.EnableAddOn or C_AddOns.DisableAddOn;

	local dependencyArray = GetAddOnDependenciesRecursive(addonName);
	for _, depAddonName in ipairs(dependencyArray) do
		setter(depAddonName, character);
	end
	setter(addonName, character);
end

function AddOnUtil.IsAddOnEnabledForCurrentCharacter(addonName)
	local character = UnitGUID("player");
	return C_AddOns.GetAddOnEnableState(addonName, character) == Enum.AddOnEnableState.All;
end
]] },
{ 'Blizzard_SharedXMLBase\\Flags.lua', [[

function Flags_CreateMask(...)
	local mask = 0;
	for i = 1, select("#", ...) do
		mask = bit.bor(mask, select(i, ...));
	end

	return mask;
end

function Flags_CreateMaskFromTable(flagsTable)
	local mask = 0;
	for flagName, flagValue in pairs(flagsTable) do
		mask = bit.bor(mask, flagValue);
	end

	return mask;
end

FlagsUtil = {};

function FlagsUtil.MakeFlags(...)
	local flags = {};
	for index = 1, select("#", ...) do
		flags[select(index,...)] = bit.lshift(1, (index-1));
	end
	return flags;
end

function FlagsUtil.IsSet(bitMask, flagOrMask)
	return bit.band(bitMask, flagOrMask) == flagOrMask;
end

function FlagsUtil.IsAnySet(bitMask, mask)
	return bit.band(bitMask, mask) ~= 0;
end

function FlagsUtil.IsAnythingSet(bitMask)
	return bitMask ~= 0;
end

function FlagsUtil.Combine(lhsFlagOrMask, rhsFlagOrMask, shouldSet)
	if shouldSet then
		return bit.bor(lhsFlagOrMask, rhsFlagOrMask);
	else
		return bit.band(lhsFlagOrMask, bit.bnot(rhsFlagOrMask));
	end
end

FlagsMixin = {};

function FlagsMixin:OnLoad(initialFlags)
	self.flags = initialFlags or 0;
end

function FlagsMixin:AddNamedFlagsFromTable(flagsTable)
	assert(flagsTable.flags == nil);
	Mixin(self, flagsTable);
end

function FlagsMixin:AddNamedMask(flagName, mask)
	assert(self[flagName] == nil);
	self[flagName] = mask;
end

function FlagsMixin:Set(flag)
	self.flags = bit.bor(self.flags, flag);
end

function FlagsMixin:Clear(flag)
	self.flags = bit.band(self.flags, bit.bnot(flag));
end

function FlagsMixin:SetOrClear(flag, isSet)
	if isSet then
		self:Set(flag);
	else
		self:Clear(flag);
	end
end

function FlagsMixin:ClearAll()
	self.flags = 0;
end

function FlagsMixin:IsAnySet()
	return self.flags ~= 0;
end

function FlagsMixin:AreNoneSet()
	return self.flags == 0;
end

function FlagsMixin:AreAnySet(flagOrMask)
	return FlagsUtil.IsAnySet(self.flags, flagOrMask);
end

function FlagsMixin:IsSet(flagOrMask)
	return FlagsUtil.IsSet(self.flags, flagOrMask);
end

function FlagsMixin:GetFlags()
	return self.flags;
end

function CreateFlags(initialFlags)
	local flags = CreateFromMixins(FlagsMixin);
	flags:OnLoad(initialFlags);
	return flags;
end

DirtyFlagsMixin = CreateFromMixins(FlagsMixin);

function DirtyFlagsMixin:OnLoad()
	FlagsMixin.OnLoad(self);
	self.isDirty = false;
end

function DirtyFlagsMixin:MarkDirty(flag)
	if flag ~= nil then
		self:Set(flag);
	end

	self.isDirty = true;
end

function DirtyFlagsMixin:MarkClean()
	self:ClearAll();
	self.isDirty = false;
end

function DirtyFlagsMixin:IsDirty(flag)
	if flag ~= nil then
		return self:IsSet(flag);
	else
		return self.isDirty;
	end
end]] },
{ 'Blizzard_SharedXMLBase\\Event.lua', [[
Event = {};

-- Callback helpers for global event callback registration that do not require a frame or owner at all
-- To unregister the event callback, call handle:Unregister() on the returned table
function Event.RegisterCallback(event, cb)
	local cbContainer = C_FunctionContainers.CreateCallback(function(_nilOwner, ...) cb(...) end);

	local handle =
	{
		Unregister = function()
			UnregisterEventCallback(event, cbContainer);
		end,
	};
	RegisterEventCallback(event, cbContainer);

	return handle;
end

function Event.RegisterUnitCallback(event, cb, unit)
	local cbContainer = C_FunctionContainers.CreateCallback(function(_nilOwner, ...) cb(...) end);

	local handle =
	{
		Unregister = function()
			UnregisterUnitEventCallback(event, cbContainer, unit);
		end,
	};
	RegisterUnitEventCallback(event, cbContainer, unit);

	return handle;
end
]] },
