{ 'Blizzard_SharedXML\\FormattingUtil.lua', [[
function SplitTextIntoLines(text, delimiter)
	local lines = {};
	local startIndex = 1;
	local foundIndex = string.find(text, delimiter);
	while foundIndex do
		table.insert(lines, text:sub(startIndex, foundIndex - 1));
		startIndex = foundIndex + 2;
		foundIndex = string.find(text, delimiter, startIndex);
	end
	if startIndex <= #text then
		table.insert(lines, text:sub(startIndex));
	end
	return lines;
end

function SplitTextIntoHeaderAndNonHeader(text)
	local foundIndex = string.find(text, "|n");
	if not foundIndex then
		-- There was no newline...the whole thing is a header
		return text;
	elseif #text == 2 then
		-- There was a newline, but that was all that was in the string.
		return nil;
	elseif foundIndex == 1 then
		-- There was a newline at the very beginning...the whole rest of the string is a header
		return text:sub(3);
	elseif foundIndex == #text - 1 then
		-- There was a newline at the very end...the whole rest of the string is a header
		return text:sub(1, foundIndex - 1);
	else
		-- There was a newline somewhere in the middle...everything before it is the header and everything after it is the non-header
		return text:sub(1, foundIndex - 1), text:sub(foundIndex + 2);
	end
end

function FormatValueWithSign(value)
	local formatString = value < 0 and SYMBOLIC_NEGATIVE_NUMBER or SYMBOLIC_POSITIVE_NUMBER;
	return formatString:format(math.abs(value));
end

function FormatLargeNumber(amount)
	amount = tostring(amount);
	local newDisplay = "";
	local strlen = amount:len();
	--Add each thing behind a comma
	for i=4, strlen, 3 do
		newDisplay = LARGE_NUMBER_SEPERATOR..amount:sub(-(i - 1), -(i - 3))..newDisplay;
	end
	--Add everything before the first comma
	newDisplay = amount:sub(1, (strlen % 3 == 0) and 3 or (strlen % 3))..newDisplay;
	return newDisplay;
end

COPPER_PER_SILVER = 100;
SILVER_PER_GOLD = 100;
COPPER_PER_GOLD = COPPER_PER_SILVER * SILVER_PER_GOLD;

local COPPER_PER_SILVER = COPPER_PER_SILVER;
local SILVER_PER_GOLD = SILVER_PER_GOLD;
local COPPER_PER_GOLD = COPPER_PER_GOLD;

MoneyStringConstants =
{
	SeparateThousands = true,
	DontSeparateThousands = false,
	CheckGoldThreshold = true,
	DontCheckGoldThreshold = false,
	ShowZeroAsGold = true,
	ShowZeroAsLowerDenomination = false,
};

function GetMoneyString(money, separateThousands, checkGoldThreshold, showZeroAsGold, color)
	local goldString, silverString, copperString;
	local gold = floor(money / (COPPER_PER_SILVER * SILVER_PER_GOLD));
	local silver = floor((money - (gold * COPPER_PER_SILVER * SILVER_PER_GOLD)) / COPPER_PER_SILVER);
	local copper = mod(money, COPPER_PER_SILVER);

	if ( CVarCallbackRegistry:GetCVarValueBool("colorblindMode") or ENABLE_COLORBLIND_MODE == "1" ) then
		if (separateThousands) then
			goldString = FormatLargeNumber(gold)..GOLD_AMOUNT_SYMBOL;
		else
			goldString = gold..GOLD_AMOUNT_SYMBOL;
		end
		silverString = silver..SILVER_AMOUNT_SYMBOL;
		copperString = copper..COPPER_AMOUNT_SYMBOL;
	else
		if (separateThousands) then
			goldString = GOLD_AMOUNT_TEXTURE_STRING:format(FormatLargeNumber(gold), 0, 0);
		else
			goldString = GOLD_AMOUNT_TEXTURE:format(gold, 0, 0);
		end
		silverString = SILVER_AMOUNT_TEXTURE:format(silver, 0, 0);
		copperString = COPPER_AMOUNT_TEXTURE:format(copper, 0, 0);
	end

	if showZeroAsGold and ( money == 0 ) then
		return color and color:WrapTextInColorCode(goldString) or goldString;
	end

	copper = FormatDisplayCopper(checkGoldThreshold, gold, silver, copper);

	local moneyString = "";
	local separator = "";
	if ( gold > 0 ) then
		moneyString = goldString;
		separator = " ";
	end
	if ( silver > 0 ) then
		moneyString = moneyString..separator..silverString;
		separator = " ";
	end
	if ( copper > 0 or moneyString == "" ) then
		moneyString = moneyString..separator..copperString;
	end

	return color and color:WrapTextInColorCode(moneyString) or moneyString;
end

function FormatDisplayCopper(checkGoldThreshold, gold, silver, copper)
	return (checkGoldThreshold and gold > Constants.MoneyFormattingConstants.GOLD_REWARD_THRESHOLD_TO_HIDE_COPPER ) and 0 or copper;
end

function FormatPercentage(percentage, roundToNearestInteger)
	if roundToNearestInteger then
		percentage = Round(percentage * 100);
	else
		percentage = percentage * 100;
	end

	return PERCENTAGE_STRING:format(percentage);
end

function FormatPercentageRounded(value)
	local roundToNearestInteger = true;
	return FormatPercentage(value, roundToNearestInteger);
end

function FormatFraction(numerator, denominator)
	return GENERIC_FRACTION_STRING:format(numerator, denominator);
end

function GetHighlightedNumberDifferenceString(baseString, newString)
	local outputString = "";
	-- output string is being built from the new string
	local newStringIndex = 1;
	-- find a stretch of digits (including . and , because of different locales) - but has to end in a digit
	local PATTERN = "([,%.%d]*%d+)";
	local start1, end1, baseNumberString = string.find(baseString, PATTERN);
	local start2, end2, newNumberString = string.find(newString, PATTERN);
	while start1 and start2 do
		-- add from the new string until the matched spot
		outputString = outputString .. string.sub(newString, newStringIndex, start2 - 1);
		newStringIndex = end2 + 1;

		if baseNumberString ~= newNumberString then
			-- need to remove , and . before comparing numbers because of locales
			local scrubbedBaseNumberString = gsub(baseNumberString, "[,%.]", "");
			local scrubbedNewNumberString = gsub(newNumberString, "[,%.]", "");
			local baseNumber = tonumber(scrubbedBaseNumberString);
			local newNumber = tonumber(scrubbedNewNumberString);
			if baseNumber and newNumber then
				local delta = newNumber - baseNumber;
				if delta > 0 then
					newNumberString = GREEN_FONT_COLOR_CODE..string.format(newNumberString)..FONT_COLOR_CODE_CLOSE;
				elseif delta < 0 then
					newNumberString = RED_FONT_COLOR_CODE..string.format(newNumberString)..FONT_COLOR_CODE_CLOSE;
				end
			end
		end

		outputString = outputString..newNumberString;

		start1, end1, baseNumberString = string.find(baseString, PATTERN, end1 + 1);
		start2, end2, newNumberString = string.find(newString, PATTERN, end2 + 1);
	end

	outputString = outputString .. string.sub(newString, newStringIndex, string.len(newString));
	return outputString;
end

function FormatUnreadMailTooltip(tooltip, headerText, senders)
	for i, sender in ipairs(senders) do
		headerText = headerText.."\n"..sender;
	end

	tooltip:SetText(headerText);
end

FormattingUtil = {};

function FormattingUtil.GetCostString(icon, quantity, colorCode, abbreviate)
	colorCode = colorCode or HIGHLIGHT_FONT_COLOR_CODE;

	local markup = CreateTextureMarkup(icon, 64, 64, 16, 16, 0, 1, 0, 1);
	local amountString;
	if abbreviate then
		amountString = AbbreviateNumbers(quantity);
	else
		amountString = BreakUpLargeNumbers(quantity);
	end
	return ("%s%s %s|r"):format(colorCode, amountString, markup);
end

function FormattingUtil.GetItemCostString(itemID, quantity, colorCode, abbreviate)
	local icon = C_Item.GetItemIconByID(itemID);
	if icon then
		return FormattingUtil.GetCostString(icon, quantity, colorCode, abbreviate);
	end

	return "";
end

function FormattingUtil.AddLeadingZeroes(digits, numZeroes, zeroesColor)
	numZeroes = numZeroes or 7;
	zeroesColor = zeroesColor or GRAY_FONT_COLOR;

	local digitsString = tostring(digits);
	local numDigits = #digitsString;
	if numDigits < numZeroes then
		local leadingZeroes = "";
		for i = 1, (numZeroes - numDigits) do
			leadingZeroes = leadingZeroes.."0";
		end

		leadingZeroes = zeroesColor:WrapTextInColorCode(leadingZeroes);

		return leadingZeroes .. digits;
	end

	return digits;
end

function GetCurrencyString(currencyID, overrideAmount, colorCode, abbreviate)
	colorCode = colorCode or HIGHLIGHT_FONT_COLOR_CODE;

	local currencyInfo = C_CurrencyInfo.GetCurrencyInfo(currencyID);
	if currencyInfo then
		local quantity = overrideAmount or currencyInfo.quantity;
		return FormattingUtil.GetCostString(currencyInfo.iconFileID, quantity, colorCode, abbreviate);
	end

	return "";
end

function GetCurrenciesString(currencies)
	local text = nil;
	for i, currency in ipairs(currencies) do
		if text then
			text = text.." ";
		else
			text = "";
		end

		if type(currency) == "table" then
			if currency.currencyID and currency.amount then
				text = text..GetCurrencyString(currency.currencyID, currency.amount, currency.colorCode);
			else
				text = text..GetCurrencyString(unpack(currency));
			end
		else
			text = text..GetCurrencyString(currency);
		end
	end

	return text;
end

function ReplaceGenderTokens(string, gender)
	if not strfind(string, "%$") then
		return string;
	end

	-- This is a very simple parser that will only handle $G/$g tokens
	return gsub(string, "$[Gg]([^:]+):([^;]+);", "%"..gender);
end
]] },
{ 'Blizzard_SharedXML\\AccountUtil.lua', [[
BNET_CLIENT_WOW = "WoW";
BNET_CLIENT_APP = "App";
BNET_CLIENT_HEROES = "Hero";
BNET_CLIENT_CLNT = "CLNT";

function GameLimitedMode_IsActive()
	return IsTrialAccount() or IsVeteranTrialAccount();
end

function GameLimitedMode_IsBankedXPActive()
	return GameLimitedMode_IsActive() or GetExpansionTrialInfo();
end

function GameLimitedMode_GetLevelLimit()
	if GetExpansionTrialInfo() then
		local level = GetMaxLevelForExpansionLevel(math.max(GetClampedCurrentExpansionLevel() - 1, 0) );
		return level;
	elseif GameLimitedMode_IsActive() then
		local level = GetRestrictedAccountData();
		return level;
	end

	local level = GetMaxLevelForPlayerExpansion();
	return level;
end

function GetClampedCurrentExpansionLevel()
	return math.min(GetClientDisplayExpansionLevel(), math.max(GetAccountExpansionLevel(), GetExpansionLevel()));
end

function IsValidEmailAddress(address)
	if address then
		local matchStart, matchEnd = string.find(address, ".+@.+%...+");
		return matchStart and matchEnd;
	end

	return false;
end

--Name can be a realID or plain battletag with no 4 digit number (e.g. Murky McGrill or LichKing).
function BNet_GetBNetIDAccount(name)
	return C_AutoComplete.GetAutoCompletePresenceID(name);
end

function BNet_GetBNetAccountName(accountInfo)
	if not accountInfo then
		return;
	end

	local name = accountInfo.accountName;
	if name == "" then
		name = BNet_GetTruncatedBattleTag(accountInfo.battleTag);
	end

	return name;
end

--Name must be a character name from your friends list.
function BNet_GetBNetIDAccountFromCharacterName(name)
	local _, numBNetOnline = BNGetNumFriends();
	for i = 1, numBNetOnline do
		local accountInfo = C_BattleNet.GetFriendAccountInfo(i);
		if accountInfo and accountInfo.gameAccountInfo.characterName and (strcmputf8i(name, accountInfo.gameAccountInfo.characterName) == 0) then
			return accountInfo.bnetAccountID;
		end
	end
end

function BNet_GetTruncatedBattleTag(battleTag)
	if battleTag then
		local symbol = string.find(battleTag, "#");
		if ( symbol ) then
			return string.sub(battleTag, 1, symbol - 1);
		else
			return battleTag;
		end
	else
		return "";
	end
end

-- if we don't have a character name or it's for a game that doesn't have toons like Heroes, use the battletag
function BNet_GetValidatedCharacterName(characterName, battleTag, client, clientTextureSize)
	if (not characterName) or (characterName == "") or (client == BNET_CLIENT_HEROES) then
		return BNet_GetTruncatedBattleTag(battleTag);
	end
	return characterName;
end

function BNet_GetValidatedCharacterNameWithClientEmbeddedAtlas(characterName, battleTag, client, texWidth, texHeight, texXOffset, texYOffset)
	return BNet_GetClientEmbeddedAtlas(client, texWidth, texHeight, texXOffset, texYOffset)..BNet_GetValidatedCharacterName(characterName, battleTag, client);
end

function BNet_GetValidatedCharacterNameWithClientEmbeddedTexture(characterName, battleTag, texture, fileWidth, fileHeight, texWidth, texHeight, texXOffset, texYOffset)
	local width = texWidth or 0;
	local height = texHeight or width;
	local xOffset = texXOffset or 0;
	local yOffset = texYOffset or 0;
	
	return CreateTextureMarkup(texture, fileWidth, fileHeight, width, height, 0, 1, 0, 1, xOffset, yOffset).." "..BNet_GetValidatedCharacterName(characterName, battleTag, client);
end]] },
{ 'Blizzard_SharedXML\\GameRulesUtil.lua', [[

GameRulesUtil = {};

GameRulesUtil.ActionButtonTypeOverlayStrategy = {
	None = 0, -- By default we show nothing.
	HighlightMana = 1, -- Show a special icon for mana spenders and a default icon for everything else.
	ManaAndEnergy = 2, -- Show a special icon for mana spenders and energy spenders and no icon for everything else.
};

-- The queue status system is a way to skin/adjust the dungeon finder eye and the dungeon
-- finder dungeon ready dialog. This is based on game mode directly instead of a game rule
-- because the display information is very specific to the game mode.
