	TitleOrCategoryCallback = "titleOrCategoryCallback",
	TeleportOutText = "teleportOutText",
	TeleportInText = "teleportInText",
	LeaveText = "leaveText",
	OverrideLFGLabelText = "overrideLFGLabelText",
	OverrideLFGNumEncounters = "overrideLFGNumEncounters",
};

