	layout.secondarySizePadding = (yPadding or layout.secondarySizePadding);
	layout.primaryMultiplier = (xMultiplier or layout.primaryMultiplier);
	layout.secondaryMultiplier = (yMultiplier or layout.secondaryMultiplier);
