	self:OnFontObjectUpdated();
end

function FontableFrameMixin:GetJustifyV()
	if self.fontObject then
		return self.fontObject:GetJustifyV();
	end
end

function FontableFrameMixin:SetIndentedWordWrap(indentWordWrap)
