end

function FontableFrameMixin:OnFontObjectUpdated()
	-- Override this function to respond to the font object changing
end

-- "private" functions
function FontableFrameMixin:MakeFontObjectCustom()
	if not self.hasOwnFontObject then
		local oldFontObject = self.fontObject;
		self.fontObject = CreateFont(tostring(self));
		if oldFontObject then
			self.fontObject:CopyFontObject(oldFontObject);
		end
		self.hasOwnFontObject = true;
	end
end]] },
{ 'Blizzard_SharedXML\\StringUtil.lua', [[
function ConfirmationStringMatches(userInput, expectedText)
	return strupper(userInput) == strupper(expectedText);
end

function ConfirmationEditBoxMatches(editBox, expectedText)
	return ConfirmationStringMatches(editBox:GetText(), expectedText);
end

function UserInputNonEmpty(userInput)
	return userInput and strtrim(userInput) ~= "";
end

function UserEditBoxNonEmpty(editBox)
	return UserInputNonEmpty(editBox:GetText());
end

function StringSplitIntoTable(sep, string)
	return { strsplit(sep, string) };
end

function StringContains(string, substring)
	local index = 1;
	local plain = true;
	return string.find(string, substring, index, plain) ~= nil;
end

StringUtil = {};

function StringUtil.RemoveTrailingSpaces(str)
	return str:match("^(.-)%s*$");
end]] },
{ 'Blizzard_SharedXML\\TypeUtil.lua', [[
--These functions are terrible, but they support legacy slash commands.
function ValueToBoolean(valueToCheck, defaultValue, defaultReturn)
	if ( type(valueToCheck) == "nil" ) then
		return false;
	elseif ( type(valueToCheck) == "boolean" ) then
		return valueToCheck;
	elseif ( type(valueToCheck) == "number" ) then
		return valueToCheck ~= 0;
	elseif ( type(valueToCheck) == "string" ) then
		return StringToBoolean(valueToCheck, defaultReturn);
	else
		return defaultReturn;
	end
end

function StringToBoolean(stringToCheck, defaultReturn)
	stringToCheck = string.lower(stringToCheck);
	local firstChar = string.sub(stringToCheck, 1, 1);

	if ( firstChar == "0" or firstChar == "n" or firstChar == "f" or stringToCheck == "off" or stringToCheck == "disabled" ) then
		return false;
	elseif ( firstChar == "1" or firstChar == "2" or firstChar == "3" or firstChar == "4" or firstChar == "5" or
				firstChar == "6" or firstChar == "7" or firstChar == "8" or firstChar == "9" or firstChar == "y" or
				firstChar == "t" or stringToCheck == "on" or stringToCheck == "enabled" ) then
		return true;
	end

	return defaultReturn;
end]] },
{ 'Blizzard_SharedXML\\SelectableButton.lua', [[
SelectableButtonMixin = {};

function SelectableButtonMixin:OnLoad()
	self.selected = false;
end

function SelectableButtonMixin:Reset()
	self.CanChangeSelectionOverride = nil;
	self.selected = false;
end

function SelectableButtonMixin:OnClick()
	return self:SetSelected(not self:IsSelected());
end

function SelectableButtonMixin:CanChangeSelection(newSelected)
	if self:IsSelected() == newSelected then
		return false;
	end

	if self.SelectionChangeInterrupt then
		return self.SelectionChangeInterrupt(self, newSelected);
	end

	return true;
end

function SelectableButtonMixin:SetSelectionChangeInterrupt(callback)
	self.SelectionChangeInterrupt = callback;
end

function SelectableButtonMixin:IsSelected()
	return not not self.selected;
end

function SelectableButtonMixin:SetSelected(newSelected)
	if self:CanChangeSelection(newSelected) then
		self:SetSelectedState(newSelected);
		self:OnSelected(newSelected);
	end
end

function SelectableButtonMixin:OnSelected(newSelected)
-- Derive
end

function SelectableButtonMixin:SetSelectedState(newSelected)
	-- Derive
	self.selected = newSelected;
end]] },
