function ScrollBoxBaseMixin:ClearEdgeFade()
	self:ClearAlphaGradient();
	self.edgeFade = nil;
end

function ScrollBoxBaseMixin:ShouldUseShadowsForEdgeFade()
	return self.alwaysUseShadowsForEdgeFade or not self:HasEdgeFade();
