function ScrollBoxBaseMixin:GetExtentPadding()
	return self:GetUpperPadding() + self:GetLowerPadding();
end

function ScrollBoxBaseMixin:GetUpperPadding()
	if self:IsHorizontal() then
		return self:GetLeftPadding();
	else
