ScrollBarMixin = CreateFromMixins(CallbackRegistryMixin, ScrollControllerMixin, EventFrameMixin);
ScrollBarMixin:GenerateCallbackEvents(
	{
		"OnScroll",
		"OnAllowScrollChanged",
	}
