		min = c - scrollPercentage * extentRemaining;
		max = c + (1.0 - scrollPercentage) * extentRemaining;
	else
		min = c - (1.0 - scrollPercentage) * extentRemaining;
		max = c + scrollPercentage * extentRemaining;
