function SyncedAnimGroupMixin:ClearSyncedStart(syncKey)
	syncKey = syncKey or self.syncKey or "DEFAULT";

	if s_animGroupSyncTimesByKey[syncKey] then
		s_animGroupSyncTimesByKey[syncKey] = nil;
	end
