	self.EditBox:SetWidth(self:GetWidth() - 18);
	self.EditBox:SetMaxLetters(self.maxLetters);
	InputScrollFrame_SetInstructions(self, self.instructions);
	self.EditBox.Instructions:SetWidth(self:GetWidth());
