				end
			end

			local str = "";
			if (goldCapForLevel > 0) then
				str = GetSecureMoneyString(goldCapForLevel * COPPER_PER_SILVER * SILVER_PER_GOLD, true, true);
			end
			return string.format(BLIZZARD_STORE_VAS_ERROR_TOO_MUCH_MONEY_FOR_LEVEL, str);
